"""FIXED build-time removal of the scored scenes for cv-3dgs-densification. Not editable.

The scored scenes are held out: their COLMAP models and images (training and
test views alike) live only in the verifier's sealed tests/meta, never in the
image. The package's data step extracts some of them anyway, so this runs once
at image build time, as root:

* ``remove`` deletes the directory of every named scene under every given data
  root, after recording the size and sha256 of every file it deletes;
* then it scans the given hash roots and fails if any file anywhere has the
  size + sha256 of a deleted file (a copy left in a cache, an archive member
  unpacked elsewhere, ...), or if a named scene directory still exists.

The development scenes are untouched (their test views stay, for local
development runs).
"""
from __future__ import annotations

import argparse
import hashlib
import os
import shutil
import sys


def _sha256(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def remove(roots, scenes, ledger: dict) -> int:
    removed = 0
    for root in roots:
        for scene in scenes:
            d = os.path.join(root, scene)
            if not os.path.isdir(d) or os.path.islink(d):
                continue
            for dp, _, fn in os.walk(d):
                for f in fn:
                    p = os.path.join(dp, f)
                    if os.path.isfile(p) and not os.path.islink(p):
                        # the scene's data: its images and its COLMAP model (a generic
                        # file such as COLMAP's project.ini is shared by other scenes)
                        rel = os.path.relpath(p, d).split(os.sep)
                        if rel[0].startswith("images") or f.endswith(".bin"):
                            ledger.setdefault(os.path.getsize(p), set()).add(_sha256(p))
                        removed += 1
            shutil.rmtree(d)
    return removed


def scan(roots, scenes, hash_roots, ledger: dict) -> list:
    problems = []
    for root in roots:
        for scene in scenes:
            if os.path.lexists(os.path.join(root, scene)):
                problems.append(f"{os.path.join(root, scene)} still exists")
    for root in hash_roots:
        for dp, dn, fn in os.walk(root, followlinks=False):
            if dp.startswith(("/proc", "/sys", "/dev")):
                dn[:] = []
                continue
            for f in fn:
                p = os.path.join(dp, f)
                try:
                    if os.path.islink(p) or not os.path.isfile(p):
                        continue
                    sz = os.path.getsize(p)
                except OSError:
                    continue
                if sz in ledger and _sha256(p) in ledger[sz]:
                    problems.append(f"{p}: bytes of a held-out scene file")
    return problems


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("cmd", choices=["remove"])
    ap.add_argument("--root", action="append", required=True,
                    help="a dataset root holding <scene>/ directories (repeatable)")
    ap.add_argument("--scene", action="append", required=True, help="a held-out scene (repeatable)")
    ap.add_argument("--hash-root", action="append", default=[],
                    help="a directory tree to scan for held-out bytes (repeatable)")
    a = ap.parse_args()
    roots = sorted({os.path.realpath(r) for r in a.root if os.path.exists(r)})
    if not roots:
        print("no data root exists", file=sys.stderr)
        return 2
    ledger: dict = {}
    n = remove(roots, a.scene, ledger)
    if n == 0:
        print(f"no file of {a.scene} found under {roots}", file=sys.stderr)
        return 2
    print(f"removed {n} files of held-out scenes {a.scene} under {roots}")
    problems = scan(roots, a.scene, [r for r in a.hash_root if os.path.isdir(r)], ledger)
    if problems:
        print("HELD-OUT SCENE DATA STILL PRESENT:\n  " + "\n  ".join(problems[:20]), file=sys.stderr)
        return 1
    print("held-out scenes absent from " + ", ".join(roots + a.hash_root))
    return 0


if __name__ == "__main__":
    sys.exit(main())

