"""FIXED per-Gaussian rasterisation statistics for cv-3dgs-densification. Not editable.

Some densification rules need quantities that only exist inside the
rasteriser's backward pass. This module computes them with a CUDA kernel that is
a copy of gsplat 1.5.3's ``rasterize_to_pixels_3dgs_bwd_kernel``
(``gsplat/cuda/csrc/RasterizeToPixels3DGSBwd.cu``): the same tile/batch walk,
the same back-to-front transmittance recovery, the same validity tests
(``sigma >= 0``, ``alpha = min(0.999, opacity * exp(-sigma)) >= 1/255``, only
Gaussians up to the pixel's last contributor) and the same per-pixel
``v_alpha`` (dL/dalpha). Instead of gsplat's parameter gradients it
accumulates, per Gaussian g, over the pixels p it contributes to:

* ``blend_grad[g] = sum_p opacity_g * dL/dalpha_{g,p}`` -- dL/dG with
  alpha = opacity * G, the quantity the ``inv_cov`` splitting-matrix estimator
  of SteepGS (Wang et al., CVPR 2025) reads from its rasteriser;
* ``dcc[g] = sum_p (u_x, u_y, 1)`` over pixels with a non-zero positional
  gradient, u = the unit vector of the per-pixel view-space positional
  gradient (dL/dmean2d of that pixel, in normalised-device units: x scaled by
  W/2, y by H/2), and ``dcc_split[g, 2k + s] = sum_p (u_x, u_y, 1, |g_x|, |g_y|)``
  over the pixels on side s (0: dot < 0, 1: dot > 0, both when 0) of the
  line through the k-th of five points along the Gaussian's projected longest
  axis (``dcc_points``: -2, -1, 0, +1, +2 standard deviations, plus the +3 end
  point that orients the test) -- the directional-consistency statistics of
  DC4GS (Jeong et al., NeurIPS 2025).

The training loop calls :func:`raster_stats` from inside the backward pass of
the training render, with exactly the tensors gsplat's own backward receives,
and hands the results to the strategy as ``info["blend_grad"]`` ([C, N]),
``info["dcc"]`` ([C, N, 3]) and ``info["dcc_split"]`` ([C, N, 10, 5]).

Built ahead of time in the image (``python mlsb_3dgs_stats.py --build``) with
the same ``TORCH_EXTENSIONS_DIR`` as gsplat's extension.
"""
from __future__ import annotations

import os
import sys

import torch

_NAME = "mlsb_3dgs_stats"

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cooperative_groups.h>
#include <cooperative_groups/reduce.h>

namespace cg = cooperative_groups;

#define MLSB_ALPHA_THRESHOLD (1.f / 255.f)

template <uint32_t CDIM, bool BLEND, bool DCC>
__global__ void raster_stats_kernel(
    const uint32_t I,
    const uint32_t n_isects,
    const float2 *__restrict__ means2d,
    const float3 *__restrict__ conics,
    const float *__restrict__ colors,
    const float *__restrict__ opacities,
    const float *__restrict__ backgrounds,
    const bool *__restrict__ masks,
    const uint32_t image_width,
    const uint32_t image_height,
    const uint32_t tile_size,
    const uint32_t tile_width,
    const uint32_t tile_height,
    const int32_t *__restrict__ tile_offsets,
    const int32_t *__restrict__ flatten_ids,
    const float *__restrict__ render_alphas,
    const int32_t *__restrict__ last_ids,
    const float *__restrict__ v_render_colors,
    const float *__restrict__ v_render_alphas,
    const float2 *__restrict__ dcc_points,   // [I * N, 5]: -2s, -1s, +1s, +2s, +3s (end)
    float *__restrict__ out_blend_grad,      // [I * N]
    float *__restrict__ out_dcc,             // [I * N, 3]
    float *__restrict__ out_dcc_split) {     // [I * N, 10, 5]
    auto block = cg::this_thread_block();
    uint32_t image_id = block.group_index().x;
    uint32_t tile_id = block.group_index().y * tile_width + block.group_index().z;
    uint32_t i = block.group_index().y * tile_size + block.thread_index().y;
    uint32_t j = block.group_index().z * tile_size + block.thread_index().x;

    tile_offsets += image_id * tile_height * tile_width;
    render_alphas += image_id * image_height * image_width;
    last_ids += image_id * image_height * image_width;
    v_render_colors += image_id * image_height * image_width * CDIM;
    v_render_alphas += image_id * image_height * image_width;
    if (backgrounds != nullptr) {
        backgrounds += image_id * CDIM;
    }
    if (masks != nullptr) {
        masks += image_id * tile_height * tile_width;
    }
    if (masks != nullptr && !masks[tile_id]) {
        return;
    }

    const float px = (float)j + 0.5f;
    const float py = (float)i + 0.5f;
    const int32_t pix_id = min(i * image_width + j, image_width * image_height - 1);
    bool inside = (i < image_height && j < image_width);
    const float half_w = 0.5f * (float)image_width;
    const float half_h = 0.5f * (float)image_height;

    int32_t range_start = tile_offsets[tile_id];
    int32_t range_end = (image_id == I - 1) && (tile_id == tile_width * tile_height - 1)
                            ? n_isects
                            : tile_offsets[tile_id + 1];
    const uint32_t block_size = block.size();
    const uint32_t num_batches = (range_end - range_start + block_size - 1) / block_size;

    extern __shared__ int s[];
    int32_t *id_batch = (int32_t *)s;
    float3 *xy_opacity_batch = reinterpret_cast<float3 *>(&id_batch[block_size]);
    float3 *conic_batch = reinterpret_cast<float3 *>(&xy_opacity_batch[block_size]);
    float *rgbs_batch = (float *)&conic_batch[block_size];
    float2 *pts_batch = reinterpret_cast<float2 *>(&rgbs_batch[block_size * CDIM]);  // [block_size * 5] if DCC

    float T_final = 1.0f - render_alphas[pix_id];
    float T = T_final;
    float buffer[CDIM] = {0.f};
    const int32_t bin_final = inside ? last_ids[pix_id] : 0;

    float v_render_c[CDIM];
#pragma unroll
    for (uint32_t k = 0; k < CDIM; ++k) {
        v_render_c[k] = v_render_colors[pix_id * CDIM + k];
    }
    const float v_render_a = v_render_alphas[pix_id];

    const uint32_t tr = block.thread_rank();
    cg::thread_block_tile<32> warp = cg::tiled_partition<32>(block);
    const int32_t warp_bin_final = cg::reduce(warp, bin_final, cg::greater<int>());
    for (uint32_t b = 0; b < num_batches; ++b) {
        block.sync();
        const int32_t batch_end = range_end - 1 - block_size * b;
        const int32_t batch_size = min(block_size, batch_end + 1 - range_start);
        const int32_t idx = batch_end - tr;
        if (idx >= range_start) {
            int32_t g = flatten_ids[idx];
            id_batch[tr] = g;
            const float2 xy = means2d[g];
            const float opac = opacities[g];
            xy_opacity_batch[tr] = {xy.x, xy.y, opac};
            conic_batch[tr] = conics[g];
#pragma unroll
            for (uint32_t k = 0; k < CDIM; ++k) {
                rgbs_batch[tr * CDIM + k] = colors[g * CDIM + k];
            }
            if (DCC) {
#pragma unroll
                for (uint32_t k = 0; k < 5; ++k) {
                    pts_batch[k * block_size + tr] = dcc_points[g * 5 + k];
                }
            }
        }
        block.sync();
        for (uint32_t t = max(0, batch_end - warp_bin_final); t < batch_size; ++t) {
            bool valid = inside;
            if (batch_end - t > bin_final) {
                valid = 0;
            }
            float alpha;
            float opac;
            float2 delta;
            float3 conic;
            float vis;
            if (valid) {
                conic = conic_batch[t];
                float3 xy_opac = xy_opacity_batch[t];
                opac = xy_opac.z;
                delta = {xy_opac.x - px, xy_opac.y - py};
                float sigma = 0.5f * (conic.x * delta.x * delta.x + conic.z * delta.y * delta.y) +
                              conic.y * delta.x * delta.y;
                vis = __expf(-sigma);
                alpha = min(0.999f, opac * vis);
                if (sigma < 0.f || alpha < MLSB_ALPHA_THRESHOLD) {
                    valid = false;
                }
            }
            if (!warp.any(valid)) {
                continue;
            }
            float blend_local = 0.f;
            float dcc_local[3] = {0.f, 0.f, 0.f};
            float split_local[50];
            if (DCC) {
#pragma unroll
                for (uint32_t q = 0; q < 50; ++q) split_local[q] = 0.f;
            }
            if (valid) {
                float ra = 1.0f / (1.0f - alpha);
                T *= ra;
                const float fac = alpha * T;
                float v_alpha = 0.f;
#pragma unroll
                for (uint32_t k = 0; k < CDIM; ++k) {
                    v_alpha += (rgbs_batch[t * CDIM + k] * T - buffer[k] * ra) * v_render_c[k];
                }
                v_alpha += T_final * ra * v_render_a;
                if (backgrounds != nullptr) {
                    float accum = 0.f;
#pragma unroll
                    for (uint32_t k = 0; k < CDIM; ++k) {
                        accum += backgrounds[k] * v_render_c[k];
                    }
                    v_alpha += -T_final * ra * accum;
                }
                if (BLEND) {
                    blend_local = opac * v_alpha;
                }
                if (DCC) {
                    const float v_sigma = -opac * vis * v_alpha;
                    const float gx = v_sigma * (conic.x * delta.x + conic.y * delta.y) * half_w;
                    const float gy = v_sigma * (conic.y * delta.x + conic.z * delta.y) * half_h;
                    const float mag = sqrtf(gx * gx + gy * gy);
                    if (mag > 0.f) {
                        const float ux = gx / mag, uy = gy / mag;
                        const float3 xyo = xy_opacity_batch[t];
                        const float2 endp = pts_batch[4 * block_size + t];
#pragma unroll
                        for (int k = 0; k < 5; ++k) {
                            float2 cur = k == 2 ? make_float2(xyo.x, xyo.y)
                                                : pts_batch[(k < 2 ? k : k - 1) * block_size + t];
                            const float dot = (endp.x - cur.x) * (px - cur.x) + (endp.y - cur.y) * (py - cur.y);
                            const int base = k * 10;
                            if (dot <= 0.f) {
                                split_local[base + 0] += ux; split_local[base + 1] += uy; split_local[base + 2] += 1.f;
                                split_local[base + 3] += fabsf(gx); split_local[base + 4] += fabsf(gy);
                            }
                            if (dot >= 0.f) {
                                split_local[base + 5] += ux; split_local[base + 6] += uy; split_local[base + 7] += 1.f;
                                split_local[base + 8] += fabsf(gx); split_local[base + 9] += fabsf(gy);
                            }
                        }
                        dcc_local[0] = ux; dcc_local[1] = uy; dcc_local[2] = 1.f;
                    }
                }
#pragma unroll
                for (uint32_t k = 0; k < CDIM; ++k) {
                    buffer[k] += rgbs_batch[t * CDIM + k] * fac;
                }
            }
            const int32_t g = id_batch[t];
            if (BLEND) {
                blend_local = cg::reduce(warp, blend_local, cg::plus<float>());
                if (warp.thread_rank() == 0) atomicAdd(out_blend_grad + g, blend_local);
            }
            if (DCC) {
#pragma unroll
                for (uint32_t q = 0; q < 3; ++q) {
                    float v = cg::reduce(warp, dcc_local[q], cg::plus<float>());
                    if (warp.thread_rank() == 0 && v != 0.f) atomicAdd(out_dcc + g * 3 + q, v);
                }
#pragma unroll
                for (uint32_t q = 0; q < 50; ++q) {
                    float v = cg::reduce(warp, split_local[q], cg::plus<float>());
                    if (warp.thread_rank() == 0 && v != 0.f) atomicAdd(out_dcc_split + g * 50 + q, v);
                }
            }
        }
    }
}

template <bool BLEND, bool DCC>
static void launch(
    uint32_t I, uint32_t n_isects, torch::Tensor &means2d, torch::Tensor &conics, torch::Tensor &colors,
    torch::Tensor &opacities, const float *bg, const bool *mk, uint32_t W, uint32_t H, uint32_t tile_size,
    uint32_t tile_width, uint32_t tile_height, torch::Tensor &tile_offsets, torch::Tensor &flatten_ids,
    torch::Tensor &render_alphas, torch::Tensor &last_ids, torch::Tensor &v_render_colors,
    torch::Tensor &v_render_alphas, const float2 *pts, float *ob, float *od, float *os) {
    dim3 threads = {tile_size, tile_size, 1};
    dim3 grid = {I, tile_height, tile_width};
    int64_t shmem = tile_size * tile_size * (sizeof(int32_t) + 2 * sizeof(float3) + sizeof(float) * 3 +
                                             (DCC ? 5 * sizeof(float2) : 0));
    TORCH_CHECK(cudaFuncSetAttribute(raster_stats_kernel<3, BLEND, DCC>,
                                     cudaFuncAttributeMaxDynamicSharedMemorySize, shmem) == cudaSuccess,
                "cannot set shared memory size");
    raster_stats_kernel<3, BLEND, DCC><<<grid, threads, shmem, at::cuda::getCurrentCUDAStream()>>>(
        I, n_isects,
        reinterpret_cast<const float2 *>(means2d.data_ptr<float>()),
        reinterpret_cast<const float3 *>(conics.data_ptr<float>()),
        colors.data_ptr<float>(), opacities.data_ptr<float>(), bg, mk, W, H, tile_size, tile_width, tile_height,
        tile_offsets.data_ptr<int32_t>(), flatten_ids.data_ptr<int32_t>(),
        render_alphas.data_ptr<float>(), last_ids.data_ptr<int32_t>(),
        v_render_colors.data_ptr<float>(), v_render_alphas.data_ptr<float>(), pts, ob, od, os);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

std::vector<torch::Tensor> raster_stats_cuda(
    torch::Tensor means2d, torch::Tensor conics, torch::Tensor colors, torch::Tensor opacities,
    c10::optional<torch::Tensor> backgrounds, c10::optional<torch::Tensor> masks,
    int64_t image_width, int64_t image_height, int64_t tile_size,
    torch::Tensor tile_offsets, torch::Tensor flatten_ids,
    torch::Tensor render_alphas, torch::Tensor last_ids,
    torch::Tensor v_render_colors, torch::Tensor v_render_alphas,
    bool want_blend, c10::optional<torch::Tensor> dcc_points) {
    TORCH_CHECK(means2d.is_cuda() && means2d.dim() >= 2, "means2d must be a CUDA [..., N, 2] tensor (packed=False)");
    TORCH_CHECK(colors.size(-1) == 3, "raster_stats supports 3 colour channels");
    means2d = means2d.contiguous(); conics = conics.contiguous(); colors = colors.contiguous();
    opacities = opacities.contiguous(); tile_offsets = tile_offsets.contiguous();
    flatten_ids = flatten_ids.contiguous(); render_alphas = render_alphas.contiguous();
    last_ids = last_ids.contiguous(); v_render_colors = v_render_colors.contiguous();
    v_render_alphas = v_render_alphas.contiguous();
    torch::Tensor bg; if (backgrounds.has_value()) bg = backgrounds.value().contiguous();
    torch::Tensor mk; if (masks.has_value()) mk = masks.value().contiguous();
    const bool want_dcc = dcc_points.has_value();
    torch::Tensor pts;
    if (want_dcc) {
        pts = dcc_points.value().contiguous();
        TORCH_CHECK(pts.numel() == opacities.numel() * 10, "dcc_points must be [..., N, 5, 2]");
    }
    auto shape = opacities.sizes().vec();
    auto blend = want_blend ? torch::zeros_like(opacities) : torch::empty({0}, opacities.options());
    auto s3 = shape; s3.push_back(3);
    auto s10 = shape; s10.push_back(10); s10.push_back(5);
    auto dcc = want_dcc ? torch::zeros(s3, opacities.options()) : torch::empty({0}, opacities.options());
    auto split = want_dcc ? torch::zeros(s10, opacities.options()) : torch::empty({0}, opacities.options());
    const uint32_t I = render_alphas.numel() / (image_height * image_width);
    const uint32_t tile_height = tile_offsets.size(-2);
    const uint32_t tile_width = tile_offsets.size(-1);
    const uint32_t n_isects = flatten_ids.size(0);
    if (n_isects == 0 || (!want_blend && !want_dcc)) return {blend, dcc, split};
    const float *bgp = backgrounds.has_value() ? bg.data_ptr<float>() : nullptr;
    const bool *mkp = masks.has_value() ? mk.data_ptr<bool>() : nullptr;
    const float2 *pp = want_dcc ? reinterpret_cast<const float2 *>(pts.data_ptr<float>()) : nullptr;
    float *ob = want_blend ? blend.data_ptr<float>() : nullptr;
    float *od = want_dcc ? dcc.data_ptr<float>() : nullptr;
    float *os = want_dcc ? split.data_ptr<float>() : nullptr;
    const uint32_t W = image_width, H = image_height, ts = tile_size;
    if (want_blend && want_dcc)
        launch<true, true>(I, n_isects, means2d, conics, colors, opacities, bgp, mkp, W, H, ts, tile_width, tile_height,
                           tile_offsets, flatten_ids, render_alphas, last_ids, v_render_colors, v_render_alphas, pp, ob, od, os);
    else if (want_blend)
        launch<true, false>(I, n_isects, means2d, conics, colors, opacities, bgp, mkp, W, H, ts, tile_width, tile_height,
                            tile_offsets, flatten_ids, render_alphas, last_ids, v_render_colors, v_render_alphas, pp, ob, od, os);
    else
        launch<false, true>(I, n_isects, means2d, conics, colors, opacities, bgp, mkp, W, H, ts, tile_width, tile_height,
                            tile_offsets, flatten_ids, render_alphas, last_ids, v_render_colors, v_render_alphas, pp, ob, od, os);
    return {blend, dcc, split};
}
"""

_CPP_SRC = r"""
#include <torch/extension.h>
std::vector<torch::Tensor> raster_stats_cuda(
    torch::Tensor means2d, torch::Tensor conics, torch::Tensor colors, torch::Tensor opacities,
    c10::optional<torch::Tensor> backgrounds, c10::optional<torch::Tensor> masks,
    int64_t image_width, int64_t image_height, int64_t tile_size,
    torch::Tensor tile_offsets, torch::Tensor flatten_ids,
    torch::Tensor render_alphas, torch::Tensor last_ids,
    torch::Tensor v_render_colors, torch::Tensor v_render_alphas,
    bool want_blend, c10::optional<torch::Tensor> dcc_points);
"""

_EXT = None


def _ext():
    global _EXT
    if _EXT is None:
        from torch.utils.cpp_extension import load_inline
        _EXT = load_inline(
            name=_NAME,
            cpp_sources=[_CPP_SRC],
            cuda_sources=[_CUDA_SRC],
            functions=["raster_stats_cuda"],
            extra_cuda_cflags=["-O3", "--use_fast_math"],
            extra_cflags=["-O3"],
            verbose=False,
        )
    return _EXT


def raster_stats(saved, width, height, tile_size, v_render_colors, v_render_alphas,
                 want_blend=True, dcc_points=None):
    """Per-Gaussian backward-pass statistics of one render.

    ``saved`` is the tuple gsplat's ``_RasterizeToPixels`` saves for its backward
    (means2d, conics, colors, opacities, backgrounds, masks, isect_offsets,
    flatten_ids, render_alphas, last_ids); the two gradients are the ones that
    backward receives. ``dcc_points`` ([C, N, 5, 2] pixel coordinates, or None)
    enables the DC4GS statistics. Returns (blend_grad [C, N] or empty,
    dcc [C, N, 3] or empty, dcc_split [C, N, 10, 5] or empty).
    """
    (means2d, conics, colors, opacities, backgrounds, masks,
     isect_offsets, flatten_ids, render_alphas, last_ids) = saved
    if v_render_alphas is None:
        v_render_alphas = torch.zeros_like(render_alphas)
    if dcc_points is not None:
        dcc_points = dcc_points.float().contiguous()
    return _ext().raster_stats_cuda(
        means2d, conics, colors, opacities, backgrounds, masks,
        int(width), int(height), int(tile_size), isect_offsets, flatten_ids,
        render_alphas.float(), last_ids, v_render_colors.float(), v_render_alphas.float(),
        bool(want_blend), dcc_points)


def blend_grad(saved, width, height, tile_size, v_render_colors, v_render_alphas):
    """sum over pixels of opacity * dL/dalpha per Gaussian ([C, N])."""
    return raster_stats(saved, width, height, tile_size, v_render_colors, v_render_alphas)[0]


@torch.no_grad()
def dcc_points(means, quats, scales, viewmats, Ks):
    """DC4GS sample points of every Gaussian in pixel coordinates ([C, N, 5, 2]).

    Along the world-space direction of the Gaussian's longest axis (column of its
    rotation matrix), at -2, -1, +1, +2 and +3 standard deviations from the mean,
    projected with the pinhole camera (the same pixel convention as gsplat's
    means2d).
    """
    q = torch.nn.functional.normalize(quats, dim=-1)
    r, x, y, z = q.unbind(-1)
    R = torch.stack([
        1 - 2 * (y * y + z * z), 2 * (x * y - r * z), 2 * (x * z + r * y),
        2 * (x * y + r * z), 1 - 2 * (x * x + z * z), 2 * (y * z - r * x),
        2 * (x * z - r * y), 2 * (y * z + r * x), 1 - 2 * (x * x + y * y),
    ], dim=-1).reshape(-1, 3, 3)
    k = torch.argmax(scales, dim=1)
    sig = scales.gather(1, k[:, None])                       # [N, 1]
    axis = R[torch.arange(len(k), device=k.device), :, k]    # [N, 3]
    signs = torch.tensor([-2.0, -1.0, 1.0, 2.0, 3.0], device=means.device)
    pts = means[:, None, :] + signs[None, :, None] * sig[:, :, None] * axis[:, None, :]   # [N, 5, 3]
    out = []
    for c in range(viewmats.shape[0]):
        Rv, tv = viewmats[c, :3, :3], viewmats[c, :3, 3]
        pc = pts @ Rv.T + tv
        zc = pc[..., 2] + 1e-7
        u = Ks[c, 0, 0] * pc[..., 0] / zc + Ks[c, 0, 2]
        v = Ks[c, 1, 1] * pc[..., 1] / zc + Ks[c, 1, 2]
        out.append(torch.stack([u, v], dim=-1))
    return torch.stack(out, 0)


if __name__ == "__main__":
    if sys.argv[1:] == ["--build"]:
        _ext()
        print(f"{_NAME} extension built in {os.environ.get('TORCH_EXTENSIONS_DIR', '(default dir)')}")
    else:
        raise SystemExit("usage: mlsb_3dgs_stats.py --build")

